    RevokeUserRole revoke(UserRoleView g,long v){return new RevokeUserRole(company,g.grantId(),v,"manual reason");}
    void sqlFailure(String state,String constraint,Runnable call){var error=catchThrowable(call::run);var p=pg(error);assertThat(p.getSQLState()).isEqualTo(state);if(constraint!=null)assertThat(p.getServerErrorMessage().getConstraint()).isEqualTo(constraint);assertThat(userRoles.translate((RuntimeException)error)).isSameAs(error);System.out.println("I3 T25 technical SQLSTATE="+state+" constraint="+p.getServerErrorMessage().getConstraint());}
