    @ParameterizedTest @ValueSource(booleans={false,true})
    void t01_t08_t09_enabledOrDisabledGrantRealSqlDtoAndParentPreservation(boolean enabled){
        var u=user("basic");if(enabled)u=users.enableUser(change(u,0));var r=role("R");var original=baseline();var parent=roleRow(r.roleId());var command=grant(u,r);var ids=new ArrayList<Map<String,Object>>();
        doAnswer(c->{c.callRealMethod();ids.add(physical());return null;}).when(userRoles).requireWritableTransaction();
        var g=service.grantRole(command);assertThat(g.grantId()).isEqualTo(command.grantId());assertThat(g.companyId()).isEqualTo(company);assertThat(g.userId()).isEqualTo(u.userId());assertThat(g.roleId()).isEqualTo(r.roleId());assertThat(g.state()).isEqualTo("UNREVOKED");assertThat(g.version()).isZero();assertThat(g.grantedAt()).isEqualTo(now);assertThat(g.revokedAt()).isNull();assertThat(g.revokeReason()).isNull();assertThat(g.revokeKind()).isNull();assertThat(queries.findUserRole(company,g.grantId())).contains(g);unchanged(original);assertThat(roleRow(r.roleId())).isEqualTo(parent);
        when(clock.instant()).thenReturn(now.plusSeconds(10));var revoked=service.revokeUserRole(revoke(g,0));assertThat(revoked.version()).isEqualTo(1);assertThat(revoked.grantedAt()).isEqualTo(now);assertThat(revoked.revokedAt()).isEqualTo(now.plusSeconds(10));assertThat(revoked.revokeKind()).isEqualTo("MANUAL");assertThat(revoked.revokeReason()).isEqualTo("manual reason");assertThat(revoked.state()).isEqualTo("REVOKED");assertThat(queries.findUserRole(company,g.grantId())).contains(revoked);var snapshot=grantRow(g.grantId());
        when(clock.instant()).thenReturn(now.plusSeconds(20));assertThat(service.revokeUserRole(new RevokeUserRole(company,g.grantId(),1L,"ignored valid reason"))).isEqualTo(revoked);failure(VERSION_CONFLICT,()->service.revokeUserRole(revoke(g,0)));assertThat(grantRow(g.grantId())).isEqualTo(snapshot);unchanged(original);assertThat(roleRow(r.roleId())).isEqualTo(parent);
        String grantSql=sql(ids.get(0));assertThat(grantSql).contains("FOR SHARE","insert into iam_user_role");int emp=grantSql.indexOf("from hr_employee"),rl=grantSql.indexOf("from iam_role"),us=grantSql.indexOf("from iam_user",rl);assertThat(emp).isGreaterThanOrEqualTo(0);assertThat(rl).isGreaterThan(emp);assertThat(us).isGreaterThan(rl);assertThat(grantSql).doesNotContain("FOR KEY SHARE","update iam_user ","update iam_role ","update hr_employee ");
        assertThat(sql(ids.get(1)).lines().filter(l->l.contains("update iam_user_role set"))).hasSize(1);assertThat(sql(ids.get(2))).doesNotContain("update iam_user_role set");
        System.out.println("I3 T01/T08/T09 enabled="+enabled+" committed grant/revoke/noop exact DTO+DB, parents unchanged; roots="+ids+"\n"+grantSql+sql(ids.get(1))+sql(ids.get(2)));
    }
    @Test void t02_t03_t06_t23_immutableIdentityHistoryAndSpecificGrantRetry(){
        var u=user("identity");var v=user("other");var r=role("R");var q=role("Q");var cmd=grant(u,r);var first=service.grantRole(cmd);var original=grantRow(first.grantId());
        var duplicate=catchThrowable(()->service.grantRole(grant(u,r)));assertThat(duplicate).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isEqualTo(USER_ROLE_ALREADY_GRANTED));assertThat(pg(duplicate).getSQLState()).isEqualTo("23505");assertThat(pg(duplicate).getServerErrorMessage().getConstraint()).isEqualTo("uq_iam_user_role_unrevoked");
        failure(GRANT_ID_CONFLICT,()->service.grantRole(new GrantRole(company,first.grantId(),v.userId(),q.roleId(),"different payload")));assertThat(grantRow(first.grantId())).isEqualTo(original);
        var old=service.revokeUserRole(revoke(first,0));var historical=grantRow(first.grantId());var second=service.grantRole(grant(u,r));failure(VERSION_CONFLICT,()->service.revokeUserRole(revoke(first,0)));assertThat(service.revokeUserRole(revoke(first,1))).isEqualTo(old);assertThat(unrevoked(r.roleId())).containsExactly(second.grantId());
        service.revokeUserRole(revoke(second,0));var third=service.grantRole(grant(u,r));assertThat(third.grantId()).isNotEqualTo(second.grantId()).isNotEqualTo(first.grantId());assertThat(rows("iam_user_role")).hasSize(3);assertThat(grantRow(first.grantId())).isEqualTo(historical);
        roles.renameRole(new RenameRole(company,r.roleId(),"renamed",r.version(),"new display name"));assertThat(grantRow(first.grantId())).isEqualTo(historical);assertThat(queries.findUserRole(company,u.userId())).isEmpty();assertThat(queries.findUserRole(company,r.roleId())).isEmpty();
        for(UUID bad:Arrays.asList(null,new UUID(0,0),UUID.fromString("00000000-0000-1000-8000-000000000001"),UUID.fromString("00000000-0000-4000-0000-000000000001")))failure(INVALID_INPUT,()->service.grantRole(new GrantRole(company,bad,u.userId(),q.roleId(),"reason")));
        System.out.println("I3 T02/T03/T06/T23 exact historical ids preserved="+rows("iam_user_role")+"; old id never targets fresh grant");
    }
