    @Test void t25_threeIndependentForeignKeyFailuresAndExactCatalog(){
        var u=user("fk");var r=role("R");UUID absentUser=UUID.randomUUID(),absentRole=UUID.randomUUID(),absentCompany=UUID.randomUUID();assertThat(jdbc.queryForObject("select count(*) from iam_user where id=?",Integer.class,absentUser)).isZero();assertThat(jdbc.queryForObject("select count(*) from iam_role where id=?",Integer.class,absentRole)).isZero();assertThat(jdbc.queryForObject("select count(*) from organization_company where id=?",Integer.class,absentCompany)).isZero();
        sqlFailure("23503","fk_iam_user_role_user",()->insert(UUID.randomUUID(),company,absentUser,r.roleId()));sqlFailure("23503","fk_iam_user_role_role",()->insert(UUID.randomUUID(),company,u.userId(),absentRole));sqlFailure("23503",null,()->insert(UUID.randomUUID(),absentCompany,u.userId(),r.roleId()));
        String catalog="select c.conname, c.conrelid::regclass::text child,c.confrelid::regclass::text parent,c.confupdtype::text update_action,c.confdeltype::text delete_action,c.condeferrable,c.condeferred,c.convalidated, array(select a.attname::text from unnest(c.conkey) with ordinality k(attnum,n) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum order by k.n)::text child_columns,array(select a.attname::text from unnest(c.confkey) with ordinality k(attnum,n) join pg_attribute a on a.attrelid=c.confrelid and a.attnum=k.attnum order by k.n)::text parent_columns from pg_constraint c where conname in ('fk_iam_user_role_user','fk_iam_user_role_role') order by conname";
        var foreign=jdbc.queryForList(catalog);assertThat(foreign).hasSize(2);for(var f:foreign){boolean user=f.get("conname").equals("fk_iam_user_role_user");assertThat(f.get("child")).isEqualTo("iam_user_role");assertThat(f.get("parent")).isEqualTo(user?"iam_user":"iam_role");assertThat(f.get("child_columns")).isEqualTo(user?"{company_id,user_id}":"{company_id,role_id}");assertThat(f.get("parent_columns")).isEqualTo("{company_id,id}");assertThat(f.get("update_action")).isEqualTo("r");assertThat(f.get("delete_action")).isEqualTo("r");assertThat(f.get("condeferrable")).isEqualTo(false);assertThat(f.get("condeferred")).isEqualTo(false);assertThat(f.get("convalidated")).isEqualTo(true);}
        var parents=jdbc.queryForList("select c.conname,c.conrelid::regclass::text parent,c.contype::text kind,c.condeferrable,c.convalidated,array(select a.attname::text from unnest(c.conkey) with ordinality k(attnum,n) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum order by k.n)::text columns, i.indisunique,i.indisvalid from pg_constraint c join pg_index i on i.indexrelid=c.conindid where conname in ('uq_iam_user_company_id','uq_iam_role_company_id') order by conname");assertThat(parents).hasSize(2);for(var p:parents){assertThat(p.get("parent")).isEqualTo(p.get("conname").equals("uq_iam_user_company_id")?"iam_user":"iam_role");assertThat(p.get("kind")).isEqualTo("u");assertThat(p.get("columns")).isEqualTo("{company_id,id}");assertThat(p.get("condeferrable")).isEqualTo(false);assertThat(p.get("convalidated")).isEqualTo(true);assertThat(p.get("indisunique")).isEqualTo(true);assertThat(p.get("indisvalid")).isEqualTo(true);}
        var idx=jdbc.queryForMap("select i.indisunique,i.indisvalid,pg_get_indexdef(i.indexrelid) definition,pg_get_expr(i.indpred,i.indrelid) predicate from pg_index i where indexrelid='uq_iam_user_role_unrevoked'::regclass");assertThat(idx.get("indisunique")).isEqualTo(true);assertThat(idx.get("indisvalid")).isEqualTo(true);assertThat(idx.get("definition").toString()).contains("(company_id, user_id, role_id)");assertThat(idx.get("predicate")).isEqualTo("(revoked_at IS NULL)");assertThat(jdbc.queryForObject("select count(*) from pg_constraint where conname='uq_iam_user_role_unrevoked'",Integer.class)).isZero();
        System.out.println("I3 T25 FR-G01 actual ordered-column catalog FKs="+foreign+" parents="+parents+" partial INDEX="+idx);
    }
    @Test void t25_dbChecksAreTechnicalAndNamedConstraints(){
        var u=user("checks");var r=role("R");UUID id=UUID.randomUUID();insert(id,company,u.userId(),r.roleId());
        var q=role("OTHER");var pk=catchThrowable(()->insert(id,company,u.userId(),q.roleId()));assertThat(pg(pk).getSQLState()).isEqualTo("23505");assertThat(pg(pk).getServerErrorMessage().getConstraint()).isEqualTo("pk_iam_user_role");assertThat(userRoles.translate((RuntimeException)pk)).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isEqualTo(GRANT_ID_CONFLICT));
        var partial=catchThrowable(()->insert(UUID.randomUUID(),company,u.userId(),r.roleId()));assertThat(pg(partial).getSQLState()).isEqualTo("23505");assertThat(pg(partial).getServerErrorMessage().getConstraint()).isEqualTo("uq_iam_user_role_unrevoked");assertThat(userRoles.translate((RuntimeException)partial)).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isEqualTo(USER_ROLE_ALREADY_GRANTED));System.out.println("I3 T25 direct PK=23505/pk_iam_user_role and partial=23505/uq_iam_user_role_unrevoked precise conversion");
        for(String fragment:List.of("revoked_at=now()","revoke_reason='reason'","revoke_kind='MANUAL'","revoked_at=now(),revoke_reason='reason',revoke_kind='OTHER'","revoked_at=now(),revoke_reason='',revoke_kind='MANUAL'"))sqlFailure("23514","ck_iam_user_role_revocation",()->jdbc.update("update iam_user_role set "+fragment+" where id=?",id));
        sqlFailure("23514","ck_iam_user_role_version",()->jdbc.update("update iam_user_role set version=-1 where id=?",id));
        for(String reason:List.of(""," "))sqlFailure("23514","ck_iam_user_role_grant_reason",()->jdbc.update("update iam_user_role set grant_reason=? where id=?",reason,id));
        sqlFailure("22001",null,()->jdbc.update("update iam_user_role set grant_reason=? where id=?","가".repeat(501),id));
        sqlFailure("23514","ck_iam_user_role_timestamps",()->jdbc.update("update iam_user_role set granted_at='infinity' where id=?",id));
        sqlFailure("23514","ck_iam_user_role_timestamps",()->jdbc.update("update iam_user_role set revoked_at='infinity',revoke_reason='reason',revoke_kind='MANUAL' where id=?",id));
        sqlFailure("23502",null,()->jdbc.update("update iam_user_role set grant_reason=null where id=?",id));
        // Unknown UNIQUE is not translated to either supported grant conflict.
        jdbc.execute("create unique index i3_unknown_unique on iam_user_role(grant_reason)");try{var another=role("Q");sqlFailure("23505","i3_unknown_unique",()->insert(UUID.randomUUID(),company,u.userId(),another.roleId()));}finally{jdbc.execute("drop index i3_unknown_unique");}
        tx(()->{jdbc.update("update iam_user_role set revoked_at=granted_at-interval '1 day',revoke_reason='earlier root instant',revoke_kind='MANUAL' where id=?",id);return null;});assertThat(grantRow(id).get("revoked_at")).isNotNull();System.out.println("I3 T25 root Instant is not commit time: no revokedAt>=grantedAt constraint");
    }
    UserRoleService withManager(PlatformTransactionManager m){return new UserRoleService(userRoles,organization,guard,m,clock,30);}
