    PlatformTransactionManager lostAck(){return new PlatformTransactionManager(){public TransactionStatus getTransaction(TransactionDefinition d){return manager.getTransaction(d);}public void commit(TransactionStatus s){manager.commit(s);throw new TransactionSystemException("test-only actual commit then lost ACK wrapper");}public void rollback(TransactionStatus s){manager.rollback(s);}};}
    @Test void t27_t28_actualCommitAckWrapperAndPreciseRetries(){
        var u=user("retry");var r=role("R");var cmd=grant(u,r);var wrapped=withManager(lostAck());assertThatThrownBy(()->wrapped.grantRole(cmd)).isInstanceOf(TransactionSystemException.class);var g=queries.findUserRole(company,cmd.grantId()).orElseThrow();var first=catchThrowable(()->service.grantRole(cmd));assertThat(first).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isIn(GRANT_ID_CONFLICT,USER_ROLE_ALREADY_GRANTED));assertThat(rows("iam_user_role")).hasSize(1);
        assertThatThrownBy(()->wrapped.revokeUserRole(revoke(g,0))).isInstanceOf(TransactionSystemException.class);failure(VERSION_CONFLICT,()->service.revokeUserRole(revoke(g,0)));var revoked=queries.findUserRole(company,g.grantId()).orElseThrow();assertThat(service.revokeUserRole(revoke(g,1))).isEqualTo(revoked);failure(GRANT_ID_CONFLICT,()->service.grantRole(cmd));
        var roleWrapped=roleWithManager(lostAck());assertThatThrownBy(()->roleWrapped.deactivateRole(change(r,1))).isInstanceOf(TransactionSystemException.class);failure(VERSION_CONFLICT,()->roles.deactivateRole(change(r,1)));failure(ROLE_INACTIVE,()->service.grantRole(cmd));assertThatThrownBy(()->roleWrapped.activateRole(change(r,2))).isInstanceOf(TransactionSystemException.class);failure(VERSION_CONFLICT,()->roles.activateRole(change(r,2)));terminations.terminateEmployee(end(u));assertThatThrownBy(()->service.grantRole(cmd)).isInstanceOf(com.kflow.erp.hr.api.HrFailure.class);assertThat(rows("iam_user_role")).hasSize(1);assertThat(grantRow(g.grantId()).get("version")).isEqualTo(1L);System.out.println("I3 T27/T28 actual grant/revoke/deactivate/activate committed then test ACK wrapper: precise retry errors, no new row/compensation; not real network or receipt guarantee");
    }
    @ParameterizedTest @ValueSource(strings={"absent","readOnly","repeatable","wrongManager","nullRC","nullRR","nullReadOnly","metadataMismatch","connectionFailure"})
    void t29_actualRootPhysicalChecks(String mode){
        if(mode.equals("absent")){failure(TRANSACTION_BOUNDARY_VIOLATION,userRoles::requireWritableTransaction);return;}
        PlatformTransactionManager m=mode.equals("wrongManager")?new org.springframework.jdbc.datasource.DataSourceTransactionManager(jdbc.getDataSource()):manager;var template=new TransactionTemplate(m);template.setIsolationLevel(mode.equals("repeatable")||mode.equals("nullRR")?TransactionDefinition.ISOLATION_REPEATABLE_READ:TransactionDefinition.ISOLATION_READ_COMMITTED);template.setReadOnly(mode.equals("readOnly")||mode.equals("nullReadOnly"));
        Runnable call=()->template.executeWithoutResult(t->{Integer isolation=TransactionSynchronizationManager.getCurrentTransactionIsolationLevel();boolean ro=TransactionSynchronizationManager.isCurrentTransactionReadOnly();if(mode.startsWith("null")){TransactionSynchronizationManager.setCurrentTransactionIsolationLevel(null);TransactionSynchronizationManager.setCurrentTransactionReadOnly(false);}if(mode.equals("metadataMismatch"))TransactionSynchronizationManager.setCurrentTransactionIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);if(mode.equals("connectionFailure")){var pid=physical().get("pid");assertThat(result(job("killer",()->jdbc.queryForObject("select pg_terminate_backend(?)",Boolean.class,pid)))).isEqualTo(true);}try{userRoles.requireWritableTransaction();if(mode.equals("nullRC"))System.out.println("I3 T29 null metadata actual RC/off same JPA Connection="+physical());}finally{TransactionSynchronizationManager.setCurrentTransactionIsolationLevel(isolation);TransactionSynchronizationManager.setCurrentTransactionReadOnly(ro);}});
        if(mode.equals("nullRC"))call.run();else if(mode.equals("connectionFailure"))assertThatThrownBy(call::run).isInstanceOf(RuntimeException.class);else failure(TRANSACTION_BOUNDARY_VIOLATION,call);
    }
