    @ParameterizedTest @ValueSource(ints={TransactionDefinition.PROPAGATION_REQUIRED,TransactionDefinition.PROPAGATION_REQUIRES_NEW,TransactionDefinition.PROPAGATION_NESTED})
    void t29_allAmbientPropagationKindsRejectPublicRootCommands(int propagation){
        var u=user("ambient");var r=role("R");var g=service.grantRole(grant(u,r));var before=rows("iam_user_role");var entered=new AtomicBoolean();
        try{tx(()->{var ambient=new TransactionTemplate(manager);ambient.setPropagationBehavior(propagation);
            if(propagation==TransactionDefinition.PROPAGATION_NESTED){
                assertThatThrownBy(()->ambient.executeWithoutResult(t->{entered.set(true);service.grantRole(grant(u,r));})).isInstanceOf(NestedTransactionNotSupportedException.class);
                assertThatThrownBy(()->ambient.executeWithoutResult(t->{entered.set(true);service.revokeUserRole(revoke(g,0));})).isInstanceOf(NestedTransactionNotSupportedException.class);
                assertThat(entered).isFalse();
            }else{failure(TRANSACTION_BOUNDARY_VIOLATION,()->ambient.executeWithoutResult(t->service.grantRole(grant(u,r))));failure(TRANSACTION_BOUNDARY_VIOLATION,()->ambient.executeWithoutResult(t->service.revokeUserRole(revoke(g,0))));}
            return null;});}catch(UnexpectedRollbackException expected){assertThat(propagation).isEqualTo(TransactionDefinition.PROPAGATION_REQUIRED);}
        assertThat(rows("iam_user_role")).isEqualTo(before);System.out.println("I3 T29 ambient propagation="+propagation+" rejects before writes; REQUIRED/REQUIRES_NEW public boundary, NESTED unsupported by actual JpaTransactionManager before command entry, no production config changed");
    }
