        var u=user("boundary");var r=role("R");var command=grant(u,r);clearInvocations(organization);failure(TRANSACTION_BOUNDARY_VIOLATION,()->tx(()->service.grantRole(command)));var wrong=withManager(new org.springframework.jdbc.datasource.DataSourceTransactionManager(jdbc.getDataSource()));failure(TRANSACTION_BOUNDARY_VIOLATION,()->wrong.grantRole(command));verify(organization,never()).getCompany();
        var ids=new ArrayList<Map<String,Object>>();doAnswer(c->{c.callRealMethod();ids.add(physical());return null;}).when(userRoles).requireWritableTransaction();doAnswer(c->{ids.add(physical());return c.callRealMethod();}).when(guard).requireGrantableEmployee(any(),any(),any());doAnswer(c->{ids.add(physical());return c.callRealMethod();}).when(userRoles).add(any());doAnswer(c->{c.callRealMethod();ids.add(physical());return null;}).when(userRoles).flush();var g=service.grantRole(command);assertThat(ids).hasSize(4).allSatisfy(id->assertThat(id).isEqualTo(ids.getFirst()));failure(TRANSACTION_BOUNDARY_VIOLATION,()->tx(()->service.revokeUserRole(revoke(g,0))));failure(TRANSACTION_BOUNDARY_VIOLATION,()->wrong.revokeUserRole(revoke(g,0)));System.out.println("I3 T29 same actual PID/XID through Root, HR Guard, insert, flush="+ids);
