    @ParameterizedTest @ValueSource(longs={0,1})
    void t26_staleManagedGrantLocallyRefreshedWithoutProbeInterference(long expected){
        var u=user("stale");var r=role("R");var g=service.grantRole(grant(u,r));UUID probe=UUID.randomUUID();jdbc.update("insert into org03_probe.org03_test_probe values(?,'before')",probe);var loaded=gate();var go=gate();var managed=new AtomicReference<UserRole>();var other=new AtomicReference<ManagedProbe>();var mode=new AtomicReference<jakarta.persistence.FlushModeType>();
        doAnswer(c->{if(thread("stale")){managed.set(em.find(UserRole.class,g.grantId()));other.set(em.find(ManagedProbe.class,probe));other.get().label("after");mode.set(em.getFlushMode());loaded.countDown();await(go);}return now;}).when(clock).instant();
        doAnswer(c->{var value=c.callRealMethod();if(thread("stale")){assertThat(value).isSameAs(managed.get());assertThat(((UserRole)value).facts().version()).isEqualTo(1);assertThat(em.contains(other.get())).isTrue();assertThat(em.getFlushMode()).isEqualTo(mode.get());assertThat(jdbc.queryForObject("select label from org03_probe.org03_test_probe where id=?",String.class,probe)).isEqualTo("before");}return value;}).when(userRoles).lockUserRole(any(),any());
        var future=job("stale",()->service.revokeUserRole(revoke(g,expected)));await(loaded);service.revokeUserRole(revoke(g,0));go.countDown();var out=result(future);if(expected==0)assertThat(out).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isEqualTo(VERSION_CONFLICT));else assertThat(out).isInstanceOfSatisfying(UserRoleView.class,v->assertThat(v.version()).isEqualTo(1));assertThat(jdbc.queryForObject("select label from org03_probe.org03_test_probe where id=?",String.class,probe)).isEqualTo(expected==0?"before":"after");System.out.println("I3 T26 local refresh latest v1, managed dirty probe unchanged until root completion expected="+expected);
    }
    @ParameterizedTest @ValueSource(strings={"role","user"})
    void t26_grantLocksUseFreshScalarFactsDespiteStaleMappedParents(String changed){
        var u=user("parent");var r=role("R");var cmd=grant(u,r);var loaded=gate();var go=gate();var roleMapped=new AtomicReference<Role>();var userMapped=new AtomicReference<User>();
        doAnswer(c->{if(thread("staleParent")){roleMapped.set(em.find(Role.class,r.roleId()));userMapped.set(em.find(User.class,u.userId()));loaded.countDown();await(go);}return now;}).when(clock).instant();
        doAnswer(c->{var facts=(UserRoleStore.RoleFacts)c.callRealMethod();if(thread("staleParent")){assertThat(facts.status()).isEqualTo(changed.equals("role")?"INACTIVE":"ACTIVE");assertThat(roleMapped.get().facts().status()).isEqualTo("ACTIVE");assertThat(em.contains(roleMapped.get())).isTrue();}return facts;}).when(userRoles).lockRoleShare(any(),any());
        doAnswer(c->{var facts=(UserRoleStore.UserFacts)c.callRealMethod();if(thread("staleParent")){assertThat(facts.status()).isEqualTo("ENABLED");assertThat(userMapped.get().facts().accountStatus()).isEqualTo("DISABLED");assertThat(em.contains(userMapped.get())).isTrue();}return facts;}).when(userRoles).lockUserShare(any(),any());
        var future=job("staleParent",()->service.grantRole(cmd));await(loaded);if(changed.equals("role"))roles.deactivateRole(change(r,1));else users.enableUser(change(u,0));go.countDown();var out=result(future);if(changed.equals("role")){assertThat(out).isInstanceOfSatisfying(IamFailure.class,f->assertThat(f.code()).isEqualTo(ROLE_INACTIVE));assertThat(rows("iam_user_role")).isEmpty();}else{assertThat(out).isInstanceOf(UserRoleView.class);assertThat(unrevoked(r.roleId())).containsExactly(cmd.grantId());}System.out.println("I3 T26 scalar locking reads latest "+changed+" while mapped parents stay stale/attached; no stale permission state");
    }
